insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('como-ejercen-las-personas-sus-derechos-sobre-sus-datos-personale','derecho',array['tecnologia','sociedad']::text[],'¿Cómo ejercen las personas sus derechos sobre sus datos personales?','Explica qué derechos tiene una persona sobre sus datos, como acceder, rectificar, cancelar y oponerse, cómo se solicitan a una empresa y qué hacer si no responde.','Guía','~20 h',20,array['Derechos ARCO','Datos personales']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho ingenieria de sistemas comunicaciones administracion ciencias politicas educacion ciencia de datos trabajo social lectura de normas. redaccion formal. diseno de guias. analisis de casos. portal de la autoridad de proteccion de datos. un editor de documentos. un editor de diagramas.',$a27sld${"id": "como-ejercen-las-personas-sus-derechos-sobre-sus-datos-personale", "area": "derecho", "areas2": ["tecnologia", "sociedad"], "titulo": "¿Cómo ejercen las personas sus derechos sobre sus datos personales?", "resumen": "Explica qué derechos tiene una persona sobre sus datos, como acceder, rectificar, cancelar y oponerse, cómo se solicitan a una empresa y qué hacer si no responde.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Derechos ARCO", "Datos personales"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Comunicaciones", "Administración", "Ciencias Políticas", "Educación", "Ciencia de Datos", "Trabajo Social"], "problema": ["La norma de protección de datos reconoce que una persona puede saber qué datos tiene una empresa sobre ella, corregirlos o pedir que se eliminen. Pero casi nadie lo sabe ni sabe cómo pedirlo.", "Convertir esos derechos en pasos concretos ayuda a ejercerlos."], "desarrollar": ["Con fuentes oficiales, resume cada derecho, cómo se ejerce, ante quién se presenta la solicitud, plazos de respuesta y qué puede hacerse si la empresa no responde.", "Redacta un modelo de solicitud para cada derecho, con un caso inventado, y una guía de pasos para presentar un reclamo ante la autoridad competente."], "ampliaciones": [{"titulo": "Simulación", "aporta": "simula con compañeros una solicitud y su respuesta."}, {"titulo": "Datos de menores", "aporta": "explica qué cambia cuando se trata de datos de menores."}, {"titulo": "Panel de privacidad", "aporta": "propón cómo una app podría facilitar el ejercicio de estos derechos."}], "objetivos": ["Conocer los derechos sobre datos.", "Redactar solicitudes.", "Conocer la ruta de reclamo.", "Explicarlo en lenguaje sencillo."], "habilidades": ["Lectura de normas.", "Redacción formal.", "Diseño de guías.", "Análisis de casos."], "herramientas": ["Portal de la autoridad de protección de datos.", "Un editor de documentos.", "Un editor de diagramas."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad competente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "El mismo enfoque sirve para explicar otros derechos de la ciudadanía, como el acceso a información pública o a servicios."}$a27sld$::jsonb,29),
('que-datos-personales-estan-protegidos-y-que-obligaciones-tienen','derecho',array['tecnologia','negocios']::text[],'¿Qué datos personales están protegidos y qué obligaciones tienen quienes los recopilan?','Identifica qué se considera dato personal y dato sensible, y qué deben hacer las organizaciones que los recopilan, como pedir consentimiento, proteger y limitar su uso.','Análisis','~20 h',20,array['Obligaciones','Datos personales']::text[],array['investigar']::text[],'publicos',NULL,'derecho administracion ingenieria de sistemas contabilidad ciencias politicas ciencia de datos comunicaciones ingenieria industrial lectura de normas. analisis de casos. elaboracion de listas de verificacion. redaccion clara. portal de la autoridad de proteccion de datos. hoja de calculo o documento. un editor de infografias.',$a28sld${"id": "que-datos-personales-estan-protegidos-y-que-obligaciones-tienen", "area": "derecho", "areas2": ["tecnologia", "negocios"], "titulo": "¿Qué datos personales están protegidos y qué obligaciones tienen quienes los recopilan?", "resumen": "Identifica qué se considera dato personal y dato sensible, y qué deben hacer las organizaciones que los recopilan, como pedir consentimiento, proteger y limitar su uso.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Obligaciones", "Datos personales"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Ingeniería de Sistemas", "Contabilidad", "Ciencias Políticas", "Ciencia de Datos", "Comunicaciones", "Ingeniería Industrial"], "problema": ["No todos los datos se tratan igual: el nombre o el correo son datos personales, y otros, como los de salud o creencias, son especialmente sensibles. Las organizaciones que los recopilan tienen obligaciones.", "Entender esas obligaciones es útil tanto para quien entrega datos como para quien monta un negocio, un registro o una aplicación."], "desarrollar": ["Con fuentes oficiales, define qué es dato personal y dato sensible, y lista las obligaciones principales de quien recopila datos, como informar, pedir consentimiento, proteger y permitir el ejercicio de derechos.", "Aplica la lista a tres casos inventados de organizaciones, por ejemplo un club, una tienda y una app, y señala qué estarían haciendo bien y qué les faltaría."], "ampliaciones": [{"titulo": "Lista para un emprendedor", "aporta": "convierte las obligaciones en una lista de verificación."}, {"titulo": "Aviso de privacidad", "aporta": "redacta un modelo para un caso inventado."}, {"titulo": "Sanciones", "aporta": "investiga qué ocurre cuando no se cumplen."}], "objetivos": ["Distinguir tipos de datos.", "Conocer obligaciones.", "Aplicarlas a casos.", "Elaborar una lista de verificación."], "habilidades": ["Lectura de normas.", "Análisis de casos.", "Elaboración de listas de verificación.", "Redacción clara."], "herramientas": ["Portal de la autoridad de protección de datos.", "Hoja de cálculo o documento.", "Un editor de infografías."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad competente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "El mismo análisis sirve para ver qué obligaciones tiene una universidad o un hospital con la información de las personas."}$a28sld$::jsonb,30),
('derechos-y-deberes-de-quienes-realizan-practicas-preprofesionale','derecho',array['educacion','negocios']::text[],'Derechos y deberes de quienes realizan prácticas preprofesionales','Elabora una guía clara de qué derechos y deberes tiene un estudiante que hace prácticas, como horario, subvención, seguro, supervisión y condiciones, y qué hacer si no se cumplen.','Guía','~22 h',22,array['Prácticas','Derechos laborales']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho administracion psicologia trabajo social economia ingenieria industrial educacion ingenieria de sistemas lectura de normas laborales. analisis de convenios. redaccion clara. diseno de guias. portal de la autoridad laboral. un convenio modelo publico. un editor de documentos.',$a29sld${"id": "derechos-y-deberes-de-quienes-realizan-practicas-preprofesionale", "area": "derecho", "areas2": ["educacion", "negocios"], "titulo": "Derechos y deberes de quienes realizan prácticas preprofesionales", "resumen": "Elabora una guía clara de qué derechos y deberes tiene un estudiante que hace prácticas, como horario, subvención, seguro, supervisión y condiciones, y qué hacer si no se cumplen.", "tipo": "Guía", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Prácticas", "Derechos laborales"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Psicología", "Trabajo Social", "Economía", "Ingeniería Industrial", "Educación", "Ingeniería de Sistemas"], "problema": ["Hacer prácticas es el primer contacto con el trabajo para muchos estudiantes, y también donde más dudas hay: ¿cuántas horas puedo trabajar?, ¿tienen que pagarme?, ¿qué seguro me corresponde? Por no preguntar, muchos aceptan condiciones que no deberían.", "Conocer lo básico permite negociar y exigir con respeto."], "desarrollar": ["Con fuentes oficiales, como la norma sobre modalidades formativas y las guías de la autoridad laboral, resume los derechos y deberes del practicante, la duración, la subvención mínima, el seguro y las condiciones del convenio.", "Redacta una guía de una página y una lista de preguntas para hacer antes de aceptar unas prácticas, y pruébala con tres estudiantes."], "ampliaciones": [{"titulo": "Señales de alerta", "aporta": "lista condiciones que deberían hacer dudar de una oferta."}, {"titulo": "Convenio paso a paso", "aporta": "explica cada parte de un convenio de prácticas modelo."}, {"titulo": "Dónde reclamar", "aporta": "indica ante qué instituciones se puede acudir."}], "objetivos": ["Conocer derechos y deberes del practicante.", "Leer un convenio modelo.", "Formular preguntas clave.", "Explicar con claridad."], "habilidades": ["Lectura de normas laborales.", "Análisis de convenios.", "Redacción clara.", "Diseño de guías."], "herramientas": ["Portal de la autoridad laboral.", "Un convenio modelo público.", "Un editor de documentos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado, a la universidad o a la autoridad laboral.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados y no incluyas nombres de empresas, jefes ni personas reales."], "otroSector": "La misma guía sirve para voluntariados, becas de trabajo o pasantías de otras carreras."}$a29sld$::jsonb,31),
('practicas-y-empleo-formal-en-que-se-diferencian','derecho',array['negocios','educacion']::text[],'Prácticas y empleo formal: ¿en qué se diferencian?','Compara un convenio de prácticas con un contrato de trabajo en aspectos como duración, pago, beneficios, horarios, supervisión y protección, para entender qué se espera y qué se puede exigir en cada uno.','Análisis','~18 h',18,array['Prácticas','Empleo']::text[],array['investigar']::text[],'publicos',NULL,'derecho administracion economia psicologia trabajo social ingenieria industrial contabilidad sociologia analisis comparativo. lectura de normas. analisis de casos. pensamiento critico. una tabla comparativa. portales oficiales. un editor de documentos.',$a30sld${"id": "practicas-y-empleo-formal-en-que-se-diferencian", "area": "derecho", "areas2": ["negocios", "educacion"], "titulo": "Prácticas y empleo formal: ¿en qué se diferencian?", "resumen": "Compara un convenio de prácticas con un contrato de trabajo en aspectos como duración, pago, beneficios, horarios, supervisión y protección, para entender qué se espera y qué se puede exigir en cada uno.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Prácticas", "Empleo"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Economía", "Psicología", "Trabajo Social", "Ingeniería Industrial", "Contabilidad", "Sociología"], "problema": ["Las prácticas y el empleo formal pueden parecerse en lo que se hace, pero legalmente son distintas. Un practicante tiene objetivos de aprendizaje y condiciones propias, mientras que un trabajador tiene relación laboral con beneficios y obligaciones diferentes.", "Confundirlos lleva a abusos en ambos sentidos."], "desarrollar": ["Con fuentes oficiales, arma una tabla comparativa con al menos diez aspectos entre un convenio de prácticas y un contrato de trabajo, como finalidad, remuneración, jornada, beneficios, seguro y terminación.", "Analiza tres casos inventados donde la diferencia no es clara y explica qué criterios ayudarían a distinguir una situación de otra."], "ampliaciones": [{"titulo": "Cuándo una práctica es un empleo", "aporta": "explica qué señales indicarían una relación laboral encubierta."}, {"titulo": "Costo para la empresa", "aporta": "compara cuánto cuesta cada figura."}, {"titulo": "Línea de carrera", "aporta": "describe cómo se pasa de practicante a trabajador."}], "objetivos": ["Comparar figuras jurídicas.", "Identificar criterios de distinción.", "Analizar casos.", "Explicar con claridad."], "habilidades": ["Análisis comparativo.", "Lectura de normas.", "Análisis de casos.", "Pensamiento crítico."], "herramientas": ["Una tabla comparativa.", "Portales oficiales.", "Un editor de documentos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado, a la universidad o a la autoridad laboral.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados y no incluyas nombres de empresas, jefes ni personas reales."], "otroSector": "La misma comparación sirve para distinguir voluntariado, trabajo independiente y empleo."}$a30sld$::jsonb,32),
('una-guia-informativa-sobre-practicas-estudiantiles','derecho',array['educacion']::text[],'Una guía informativa sobre prácticas estudiantiles','Diseña una guía para estudiantes que van a empezar prácticas, con qué buscar, qué documentos preparar, qué preguntar, cómo comportarse y qué hacer ante un problema.','Guía','~20 h',20,array['Prácticas','Guía']::text[],array['crear']::text[],'publicos',NULL,'derecho educacion administracion comunicaciones diseno psicologia ingenieria de sistemas trabajo social diseno de contenidos. redaccion clara. pruebas con usuarios. lectura de normas. un editor de documentos o infografias. un formulario de opinion. portales oficiales.',$a31sld${"id": "una-guia-informativa-sobre-practicas-estudiantiles", "area": "derecho", "areas2": ["educacion"], "titulo": "Una guía informativa sobre prácticas estudiantiles", "resumen": "Diseña una guía para estudiantes que van a empezar prácticas, con qué buscar, qué documentos preparar, qué preguntar, cómo comportarse y qué hacer ante un problema.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Prácticas", "Guía"], "intencion": ["crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Educación", "Administración", "Comunicaciones", "Diseño", "Psicología", "Ingeniería de Sistemas", "Trabajo Social"], "problema": ["Los estudiantes llegan a su primera experiencia profesional con muchas dudas y poca orientación. La información existe, pero está dispersa entre la universidad, la empresa y las normas.", "Una guía que junte todo, en orden cronológico, puede evitar errores y ansiedad."], "desarrollar": ["Organiza la guía en etapas: antes de postular, durante la selección, antes de firmar, durante las prácticas y al terminar, con consejos concretos y enlaces oficiales para cada una.", "Pídele a cinco estudiantes que la lean y marquen qué falta o no se entiende, y mejórala con esos comentarios."], "ampliaciones": [{"titulo": "Lista de verificación", "aporta": "crea un checklist para cada etapa."}, {"titulo": "Por carrera", "aporta": "adapta ejemplos para distintas carreras."}, {"titulo": "Preguntas de entrevista", "aporta": "añade preguntas que el estudiante puede hacer a la empresa."}], "objetivos": ["Organizar información por etapas.", "Redactar una guía útil.", "Validarla con usuarios.", "Mejorarla."], "habilidades": ["Diseño de contenidos.", "Redacción clara.", "Pruebas con usuarios.", "Lectura de normas."], "herramientas": ["Un editor de documentos o infografías.", "Un formulario de opinión.", "Portales oficiales."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado, a la universidad o a la autoridad laboral.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "No incluyas nombres de empresas ni ejemplos que identifiquen a alguien."], "otroSector": "La misma guía sirve para orientar en becas, intercambios o primeras ofertas laborales."}$a31sld$::jsonb,33),
('casos-ficticios-sobre-derechos-laborales-de-estudiantes-y-jovene','derecho',array['educacion','sociedad']::text[],'Casos ficticios sobre derechos laborales de estudiantes y jóvenes','Escribe y analiza casos inventados de situaciones laborales comunes de estudiantes, como horas extras no pagadas o cambios de funciones, y discute qué derechos estarían en juego y qué se podría hacer.','Análisis','~20 h',20,array['Casos','Derechos laborales']::text[],array['investigar','crear']::text[],'ficticios',NULL,'derecho psicologia administracion trabajo social sociologia educacion economia comunicaciones analisis de casos. razonamiento juridico basico. redaccion clara. comunicacion asertiva. un editor de documentos. portales oficiales. un formulario para recoger opiniones.',$a32sld${"id": "casos-ficticios-sobre-derechos-laborales-de-estudiantes-y-jovene", "area": "derecho", "areas2": ["educacion", "sociedad"], "titulo": "Casos ficticios sobre derechos laborales de estudiantes y jóvenes", "resumen": "Escribe y analiza casos inventados de situaciones laborales comunes de estudiantes, como horas extras no pagadas o cambios de funciones, y discute qué derechos estarían en juego y qué se podría hacer.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Casos", "Derechos laborales"], "intencion": ["investigar", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Derecho", "Psicología", "Administración", "Trabajo Social", "Sociología", "Educación", "Economía", "Comunicaciones"], "problema": ["Las situaciones de trabajo no siempre son claras: una tarea fuera del horario, una promesa verbal o una función distinta a la acordada. Los estudiantes a veces no saben si lo que viven es normal.", "Los casos permiten practicar el análisis sin exponer a nadie y aprender a reconocer cuándo pedir ayuda."], "desarrollar": ["Redacta seis casos inventados y variados, y para cada uno identifica los hechos, las normas aplicables, los derechos posiblemente afectados y las opciones del joven.", "Escribe una breve resolución de cada caso, con pasos prácticos, y comparte los casos con compañeros para que propongan soluciones antes de ver la tuya."], "ampliaciones": [{"titulo": "Juego de roles", "aporta": "organiza una dinámica donde cada persona representa a una parte."}, {"titulo": "Diálogo", "aporta": "redacta cómo plantear el problema con calma ante un supervisor."}, {"titulo": "Mapa de ayuda", "aporta": "añade a quién acudir en cada caso."}], "objetivos": ["Redactar casos con hechos claros.", "Identificar derechos en juego.", "Proponer soluciones prácticas.", "Debatir con respeto."], "habilidades": ["Análisis de casos.", "Razonamiento jurídico básico.", "Redacción clara.", "Comunicación asertiva."], "herramientas": ["Un editor de documentos.", "Portales oficiales.", "Un formulario para recoger opiniones."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado, a la universidad o a la autoridad laboral.", "Trabaja con casos inventados y no incluyas nombres de empresas, jefes ni personas reales.", "No te bases en experiencias de personas identificables ni uses los casos para acusar a empresas."], "otroSector": "La misma técnica de casos sirve para la formación en convivencia, en ética profesional y en resolución de conflictos."}$a32sld$::jsonb,34),
('que-responsabilidades-tiene-una-organizacion-con-sus-practicante','derecho',array['negocios','educacion']::text[],'¿Qué responsabilidades tiene una organización con sus practicantes?','Explica qué condiciones debe cumplir una empresa o institución para recibir practicantes y qué responsabilidades asume, como convenio, supervisión, seguro y condiciones de seguridad.','Guía','~18 h',18,array['Empresas','Practicantes']::text[],array['investigar','otro-sector']::text[],'publicos',NULL,'derecho administracion psicologia economia ingenieria industrial trabajo social contabilidad comunicaciones lectura de normas. gestion de personas. diseno de planes. redaccion clara. portales oficiales. hoja de calculo o documento. un editor de presentaciones.',$a33sld${"id": "que-responsabilidades-tiene-una-organizacion-con-sus-practicante", "area": "derecho", "areas2": ["negocios", "educacion"], "titulo": "¿Qué responsabilidades tiene una organización con sus practicantes?", "resumen": "Explica qué condiciones debe cumplir una empresa o institución para recibir practicantes y qué responsabilidades asume, como convenio, supervisión, seguro y condiciones de seguridad.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Empresas", "Practicantes"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Psicología", "Economía", "Ingeniería Industrial", "Trabajo Social", "Contabilidad", "Comunicaciones"], "problema": ["Recibir practicantes no es solo darles una tarea: implica firmar un convenio, designar a quien los supervise, asegurarlos y asegurar que aprendan algo útil. Muchas organizaciones pequeñas lo desconocen.", "Entender esas responsabilidades ayuda a quien recibe y a quien llega."], "desarrollar": ["Con fuentes oficiales, lista las condiciones y responsabilidades de una organización que incorpora practicantes, como el convenio, el plan de aprendizaje, la supervisión, el seguro, la jornada y las condiciones de seguridad.", "Arma una lista de verificación para una organización inventada y evalúa si cumple, y un plan de bienvenida y aprendizaje para el practicante."], "ampliaciones": [{"titulo": "Plan de aprendizaje", "aporta": "diseña un plan de seis semanas con objetivos."}, {"titulo": "Evaluación", "aporta": "crea una ficha de evaluación justa para el practicante."}, {"titulo": "Riesgos", "aporta": "identifica riesgos de salud y seguridad según el tipo de empresa."}], "objetivos": ["Conocer responsabilidades de la organización.", "Elaborar una lista de verificación.", "Diseñar un plan de aprendizaje.", "Evaluar casos."], "habilidades": ["Lectura de normas.", "Gestión de personas.", "Diseño de planes.", "Redacción clara."], "herramientas": ["Portales oficiales.", "Hoja de cálculo o documento.", "Un editor de presentaciones."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado, a la universidad o a la autoridad laboral.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados y no incluyas nombres de empresas, jefes ni personas reales."], "otroSector": "La misma lista sirve para organizaciones que reciben voluntarios, becarios o pasantes."}$a33sld$::jsonb,35),
('beneficios-y-obligaciones-en-distintas-modalidades-de-practica','derecho',array['educacion','negocios']::text[],'Beneficios y obligaciones en distintas modalidades de práctica','Compara las modalidades en que se pueden realizar prácticas, como preprofesionales, profesionales o laborales, con sus beneficios, duración, pago y obligaciones.','Análisis','~18 h',18,array['Modalidades formativas','Comparación']::text[],array['investigar']::text[],'publicos',NULL,'derecho administracion economia educacion trabajo social psicologia contabilidad sociologia lectura de normas. analisis comparativo. elaboracion de recomendaciones. comunicacion clara. una tabla comparativa. portales oficiales. un editor de documentos.',$a34sld${"id": "beneficios-y-obligaciones-en-distintas-modalidades-de-practica", "area": "derecho", "areas2": ["educacion", "negocios"], "titulo": "Beneficios y obligaciones en distintas modalidades de práctica", "resumen": "Compara las modalidades en que se pueden realizar prácticas, como preprofesionales, profesionales o laborales, con sus beneficios, duración, pago y obligaciones.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Modalidades formativas", "Comparación"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Economía", "Educación", "Trabajo Social", "Psicología", "Contabilidad", "Sociología"], "problema": ["No todas las prácticas son iguales: según la modalidad cambian la duración, la subvención, los beneficios y las obligaciones de ambas partes. Muchos estudiantes no saben en cuál están o a cuál podrían acceder.", "Compararlas ayuda a elegir y a exigir lo que corresponde."], "desarrollar": ["Con fuentes oficiales, identifica las modalidades vigentes de prácticas y de formación laboral y compáralas en una tabla con aspectos como a quién se dirigen, duración, pago, beneficios y terminación.", "Aplica la comparación a tres perfiles inventados, como un estudiante de cuarto ciclo, un egresado y una persona que cambia de carrera, y recomienda qué modalidad le convendría y por qué."], "ampliaciones": [{"titulo": "Línea de tiempo", "aporta": "dibuja un recorrido típico de un estudiante hasta su primer empleo."}, {"titulo": "Costo y beneficio", "aporta": "estima cuánto percibe un estudiante en cada modalidad."}, {"titulo": "Cambios recientes", "aporta": "investiga qué cambió en las normas en los últimos años."}], "objetivos": ["Identificar modalidades de prácticas.", "Compararlas en una tabla.", "Aplicar criterios a perfiles.", "Recomendar con argumentos."], "habilidades": ["Lectura de normas.", "Análisis comparativo.", "Elaboración de recomendaciones.", "Comunicación clara."], "herramientas": ["Una tabla comparativa.", "Portales oficiales.", "Un editor de documentos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado, a la universidad o a la autoridad laboral.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados y no incluyas nombres de empresas, jefes ni personas reales."], "otroSector": "La misma comparación sirve para modalidades de trabajo, de contratos o de becas."}$a34sld$::jsonb,36),
('guia-para-comprender-una-boleta-de-pago-y-sus-principales-concep','derecho',array['negocios','educacion']::text[],'Guía para comprender una boleta de pago y sus principales conceptos','Explica qué significan los conceptos de una boleta de pago, como remuneración, descuentos, aportes y beneficios, usando una boleta modelo inventada, para que cualquier trabajador la entienda.','Guía','~16 h',16,array['Boleta de pago','Remuneración']::text[],array['crear','resolver']::text[],'ficticios',NULL,'contabilidad derecho administracion economia trabajo social educacion ingenieria industrial comunicaciones lectura de documentos contables. calculo basico. redaccion clara. diseno de guias. hoja de calculo. una boleta modelo inventada. normas laborales oficiales.',$a35sld${"id": "guia-para-comprender-una-boleta-de-pago-y-sus-principales-concep", "area": "derecho", "areas2": ["negocios", "educacion"], "titulo": "Guía para comprender una boleta de pago y sus principales conceptos", "resumen": "Explica qué significan los conceptos de una boleta de pago, como remuneración, descuentos, aportes y beneficios, usando una boleta modelo inventada, para que cualquier trabajador la entienda.", "tipo": "Guía", "tiempo": "~16 h", "horas": 16, "etiquetas": ["Boleta de pago", "Remuneración"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Contabilidad", "Derecho", "Administración", "Economía", "Trabajo Social", "Educación", "Ingeniería Industrial", "Comunicaciones"], "problema": ["Cuando alguien recibe su primera boleta de pago, suele ver números y siglas que no entiende: aportes, descuentos, bonificaciones. Eso dificulta saber si el monto es correcto.", "Una guía sencilla ayuda a verificar lo que corresponde y a hacer preguntas cuando algo no cuadra."], "desarrollar": ["Diseña una boleta modelo inventada con los conceptos más comunes y explica en lenguaje sencillo qué significa cada uno, de dónde sale el monto y quién lo recibe.", "Prepara tres ejemplos con cálculos simples para distintos casos, como un practicante, un trabajador a tiempo completo y un independiente, y una lista de preguntas para revisar la boleta."], "ampliaciones": [{"titulo": "Calculadora", "aporta": "crea una hoja que calcule los conceptos desde el sueldo bruto."}, {"titulo": "Errores comunes", "aporta": "lista errores que suelen aparecer en boletas."}, {"titulo": "Independientes", "aporta": "explica qué documento reemplaza a la boleta para quienes trabajan por su cuenta."}], "objetivos": ["Comprender los conceptos de una boleta.", "Explicarlos en lenguaje sencillo.", "Hacer cálculos simples.", "Detectar posibles errores."], "habilidades": ["Lectura de documentos contables.", "Cálculo básico.", "Redacción clara.", "Diseño de guías."], "herramientas": ["Hoja de cálculo.", "Una boleta modelo inventada.", "Normas laborales oficiales."], "lineamientos": ["Usa solo una boleta inventada y nunca la boleta real de una persona.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado, a la universidad o a la autoridad laboral.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian."], "otroSector": "La misma guía sirve para entender recibos de servicios, estados de cuenta o facturas."}$a35sld$::jsonb,37),
('propiedad-intelectual-de-los-contenidos-creados-por-estudiantes','derecho',array['educacion','arte']::text[],'Propiedad intelectual de los contenidos creados por estudiantes','Aclara quién es dueño de un trabajo hecho por un estudiante, como una fotografía, un video, un texto o un programa, y qué pasa cuando se hizo en grupo o dentro de un curso.','Guía','~20 h',20,array['Derechos de autor','Estudiantes']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho educacion diseno comunicaciones ingenieria de sistemas arquitectura administracion psicologia lectura de normas. analisis de casos. redaccion de acuerdos. comunicacion clara. portales oficiales. reglamentos publicos de universidades. un editor de documentos.',$a36sld${"id": "propiedad-intelectual-de-los-contenidos-creados-por-estudiantes", "area": "derecho", "areas2": ["educacion", "arte"], "titulo": "Propiedad intelectual de los contenidos creados por estudiantes", "resumen": "Aclara quién es dueño de un trabajo hecho por un estudiante, como una fotografía, un video, un texto o un programa, y qué pasa cuando se hizo en grupo o dentro de un curso.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Derechos de autor", "Estudiantes"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Educación", "Diseño", "Comunicaciones", "Ingeniería de Sistemas", "Arquitectura", "Administración", "Psicología"], "problema": ["Los estudiantes crean mucho material: informes, códigos, diseños, videos. Pero cuando se hace en un curso, con apoyo de un docente o en equipo, surge la duda de quién tiene los derechos y cómo se puede usar o publicar.", "Conocer las reglas evita conflictos y permite proteger y compartir lo que uno crea."], "desarrollar": ["Con fuentes oficiales y reglamentos públicos de instituciones, resume cómo se asignan los derechos de autor en trabajos de estudiantes, qué cambia en trabajos grupales y qué dicen las universidades sobre la propiedad intelectual.", "Redacta cinco casos inventados, como un proyecto de curso, una tesis, un video grupal y un software hecho en prácticas, y explica para cada uno quién tendría derechos y qué conviene acordar."], "ampliaciones": [{"titulo": "Acuerdo de equipo", "aporta": "crea un modelo de acuerdo de autoría para un trabajo grupal."}, {"titulo": "Cuando hay una empresa", "aporta": "analiza qué pasa con lo creado en prácticas."}, {"titulo": "Cómo dar créditos", "aporta": "propón una forma clara de reconocer a cada persona."}], "objetivos": ["Conocer reglas de autoría.", "Aplicarlas a casos de estudiantes.", "Elaborar un acuerdo de equipo.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Análisis de casos.", "Redacción de acuerdos.", "Comunicación clara."], "herramientas": ["Portales oficiales.", "Reglamentos públicos de universidades.", "Un editor de documentos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad de derechos de autor.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados y no uses obras de otras personas como ejemplo sin citarlas."], "otroSector": "La misma guía sirve para proyectos de investigación, de software abierto y de colectivos creativos."}$a36sld$::jsonb,38),
('quien-es-el-autor-de-una-obra-y-que-derechos-tiene','derecho',array['arte']::text[],'¿Quién es el autor de una obra y qué derechos tiene?','Explica qué significa ser autor, qué derechos morales y patrimoniales tiene y qué pasa cuando varias personas colaboran o cuando se usa una herramienta para crear.','Guía','~15 h',15,array['Autoría','Derechos']::text[],array['investigar']::text[],'publicos',NULL,'derecho diseno comunicaciones educacion ingenieria de sistemas arquitectura sociologia administracion lectura de normas. analisis de casos. pensamiento juridico basico. comunicacion clara. portal de la autoridad de derechos de autor. un editor de documentos. casos inventados.',$a37sld${"id": "quien-es-el-autor-de-una-obra-y-que-derechos-tiene", "area": "derecho", "areas2": ["arte"], "titulo": "¿Quién es el autor de una obra y qué derechos tiene?", "resumen": "Explica qué significa ser autor, qué derechos morales y patrimoniales tiene y qué pasa cuando varias personas colaboran o cuando se usa una herramienta para crear.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Autoría", "Derechos"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Diseño", "Comunicaciones", "Educación", "Ingeniería de Sistemas", "Arquitectura", "Sociología", "Administración"], "problema": ["Se dice que alguien es autor de una canción o de un texto, pero ¿qué implica eso? El autor tiene derechos sobre cómo se usa su obra, quién puede copiarla y cómo se le reconoce. Esos derechos pueden compartirse o cederse.", "Hoy, con herramientas digitales y de inteligencia artificial, la pregunta por la autoría se complica."], "desarrollar": ["Con fuentes oficiales, define autor, obra, derechos morales y patrimoniales, y explícalos con ejemplos sencillos.", "Analiza cinco casos inventados de autoría, como una obra colectiva, una obra por encargo, una obra creada con apoyo de una herramienta y una obra anónima, y explica quién sería el autor y qué derechos tendría."], "ampliaciones": [{"titulo": "Obras con inteligencia artificial", "aporta": "investiga cómo se discute la autoría de obras generadas por IA."}, {"titulo": "Duración de los derechos", "aporta": "explica cuánto tiempo duran y qué pasa después."}, {"titulo": "Registro", "aporta": "describe cómo registrar una obra y para qué sirve."}], "objetivos": ["Comprender el concepto de autor.", "Distinguir derechos morales y patrimoniales.", "Analizar casos.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Análisis de casos.", "Pensamiento jurídico básico.", "Comunicación clara."], "herramientas": ["Portal de la autoridad de derechos de autor.", "Un editor de documentos.", "Casos inventados."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad de derechos de autor.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados y no uses obras de otras personas como ejemplo sin citarlas."], "otroSector": "El mismo análisis sirve para autoría de software, de datos de investigación o de contenidos en redes."}$a37sld$::jsonb,39),
('licencias-para-compartir-contenido-de-manera-legal-incluidas-las','derecho',array['arte','tecnologia']::text[],'Licencias para compartir contenido de manera legal, incluidas las Creative Commons','Explica cómo funcionan las licencias que permiten compartir obras, en especial las Creative Commons, qué permite cada una y cómo elegir la adecuada para tu propio trabajo.','Guía','~18 h',18,array['Licencias','Creative Commons']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho diseno ingenieria de sistemas comunicaciones educacion ciencia de datos administracion arquitectura lectura de licencias. analisis comparativo. pensamiento juridico basico. diseno de guias. portales oficiales de las licencias. un editor de diagramas. un editor de documentos.',$a38sld${"id": "licencias-para-compartir-contenido-de-manera-legal-incluidas-las", "area": "derecho", "areas2": ["arte", "tecnologia"], "titulo": "Licencias para compartir contenido de manera legal, incluidas las Creative Commons", "resumen": "Explica cómo funcionan las licencias que permiten compartir obras, en especial las Creative Commons, qué permite cada una y cómo elegir la adecuada para tu propio trabajo.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Licencias", "Creative Commons"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Diseño", "Ingeniería de Sistemas", "Comunicaciones", "Educación", "Ciencia de Datos", "Administración", "Arquitectura"], "problema": ["Compartir contenido en internet no significa que cualquiera pueda usarlo como quiera. Las licencias dicen qué se puede hacer con una obra, como copiarla, modificarla, venderla o exigir que se cite al autor.", "Las licencias Creative Commons son una forma popular de dar permisos claros, pero tienen varias combinaciones que conviene entender."], "desarrollar": ["Con la información oficial de las licencias, resume cada tipo con sus condiciones, como atribución, uso no comercial, sin obras derivadas y compartir igual, y arma una tabla comparativa.", "Elige cinco obras de ejemplo con licencia y explica qué podrías hacer o no con cada una en un proyecto, y crea un diagrama que ayude a elegir la licencia para una obra propia."], "ampliaciones": [{"titulo": "Cómo citar bien", "aporta": "muestra cómo dar los créditos exigidos por cada licencia."}, {"titulo": "Licencias de software", "aporta": "compara con licencias de código abierto."}, {"titulo": "Elegir una licencia", "aporta": "decide qué licencia usarías para un proyecto estudiantil y por qué."}], "objetivos": ["Comprender el sistema de licencias.", "Comparar tipos de licencia.", "Aplicarlas a casos.", "Elegir una licencia para un proyecto propio."], "habilidades": ["Lectura de licencias.", "Análisis comparativo.", "Pensamiento jurídico básico.", "Diseño de guías."], "herramientas": ["Portales oficiales de las licencias.", "Un editor de diagramas.", "Un editor de documentos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad de derechos de autor.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Ante dudas sobre si una licencia aplica a tu caso, consulta el texto completo y, si es importante, a un profesional."], "otroSector": "La misma guía sirve para repositorios de código, bancos de imágenes o materiales educativos abiertos."}$a38sld$::jsonb,40),
('guia-de-derechos-de-autor-para-principiantes','derecho',array['educacion','arte']::text[],'Guía de derechos de autor para principiantes','Crea una guía corta y visual para quien nunca ha estudiado derechos de autor, con qué se protege, qué no, qué se puede usar y qué conviene preguntar antes de publicar algo.','Guía','~20 h',20,array['Derechos de autor','Guía']::text[],array['crear']::text[],'publicos',NULL,'derecho educacion diseno comunicaciones ingenieria de sistemas psicologia arquitectura administracion sintesis. diseno de materiales. redaccion clara. pruebas con usuarios. un editor de infografias. fuentes oficiales. un formulario de opinion.',$a39sld${"id": "guia-de-derechos-de-autor-para-principiantes", "area": "derecho", "areas2": ["educacion", "arte"], "titulo": "Guía de derechos de autor para principiantes", "resumen": "Crea una guía corta y visual para quien nunca ha estudiado derechos de autor, con qué se protege, qué no, qué se puede usar y qué conviene preguntar antes de publicar algo.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Derechos de autor", "Guía"], "intencion": ["crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Educación", "Diseño", "Comunicaciones", "Ingeniería de Sistemas", "Psicología", "Arquitectura", "Administración"], "problema": ["Los derechos de autor suenan técnicos y complicados, pero afectan a cualquiera que suba fotos, comparta música o use imágenes en una presentación. Muchas infracciones ocurren por ignorancia y no por mala intención.", "Una guía con ejemplos cotidianos facilita entenderlo."], "desarrollar": ["Define diez ideas esenciales, como qué está protegido, qué es de uso libre, qué es una cita legítima, cuándo se necesita permiso y cómo dar crédito, y explícalas con ejemplos de la vida estudiantil.", "Diseña la guía como un folleto o una infografía, pruébala con cinco compañeros y ajústala según sus dudas."], "ampliaciones": [{"titulo": "Preguntas frecuentes", "aporta": "añade una sección con las dudas más comunes."}, {"titulo": "Mitos", "aporta": "explica creencias erradas, como que todo en internet es libre."}, {"titulo": "Versión animada", "aporta": "crea un video breve con los puntos principales."}], "objetivos": ["Seleccionar ideas esenciales.", "Explicarlas con ejemplos cotidianos.", "Diseñar una guía visual.", "Validarla con lectores."], "habilidades": ["Síntesis.", "Diseño de materiales.", "Redacción clara.", "Pruebas con usuarios."], "herramientas": ["Un editor de infografías.", "Fuentes oficiales.", "Un formulario de opinión."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad de derechos de autor.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Usa imágenes propias, de dominio público o con licencia para ilustrar tu guía."], "otroSector": "La misma guía sirve para explicar normas de citación en trabajos académicos o de reutilización de datos."}$a39sld$::jsonb,41)
